{
  "concepts": [
    {
      "conditions": [],
      "definition": "The runtime role owning traversal, dispatch, actor invocation, process supervision, graph-call realisation, runtime facts, runtime event emission and replay, frames, continuations, retry and correction control, closure folds over runtime truth, re-entry after publication, lineage and provenance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 591,
          "quote": "ABG owns traversal; dispatch; actor invocation; process supervision;\ngraph-call realisation; runtime facts; runtime event emission and replay;\nframes; continuations; retry and correction control; closure folds over\nruntime truth; re-entry after publish boundaries; lineage and provenance\n(P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FABG",
          "start_line": 587
        }
      ],
      "key": "abg",
      "label": "ABG"
    },
    {
      "conditions": [],
      "definition": "Domain product owning domain asset meaning, graph-function meaning, the published function catalogue, policy overlays, domain query projections, and domain closure and gap interpretation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 597,
          "quote": "The ODD product owns domain asset meaning, graph-function meaning, the\npublished function catalogue, policy overlays, domain query projections,\nand closure and gap interpretation for its domain (P6, P1).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FODD%20product",
          "start_line": 595
        }
      ],
      "key": "odd_product",
      "label": "ODD product"
    },
    {
      "conditions": [],
      "definition": "Service and query surfaces whose possible responsibilities include transport, sessions, routing, browser-safe projection and APIs, without runtime or continuation ownership.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 603,
          "quote": "Service or query layers may own transport, sessions, routing,\nbrowser-safe projection and API surfaces. They own neither runtime truth\nnor continuation truth.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FQuery%20and%20service%20layers",
          "start_line": 601
        }
      ],
      "key": "service_query_layers",
      "label": "Query and service layers"
    },
    {
      "conditions": [],
      "definition": "Explicit typed assets or nodes within typed domain boundaries; asset_surface identifies a real produced or consumed asset boundary.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 617,
          "quote": "Concrete assets must bind explicitly into\ntyped domain boundaries. Where an asset is a real produced or consumed boundary,\nits `asset_surface` is declared (P3).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.1%20Typed%20assets%20and%20nodes%20are%20explicit",
          "start_line": 615
        }
      ],
      "key": "typed_assets",
      "label": "Typed assets and nodes"
    },
    {
      "conditions": [],
      "definition": "Named constructive program, or lawful composition of such programs, carrying an operative constructive step.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 622,
          "quote": "Every operative constructive step is carried by one named `GraphFunction`\nor one lawful graph-function composition.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.2%20Graph%20functions%20are%20the%20primary%20constructive%20carrier",
          "start_line": 621
        }
      ],
      "key": "graph_function",
      "label": "GraphFunction"
    },
    {
      "conditions": [],
      "definition": "Pre-implementation declaration of governed movement: source and target asset types; edge traversal or graph-function name; closure or evaluation, lineage, and ambiguity or gap obligations; allowed F_D, F_P and F_H bindings.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 639,
          "quote": "An outcome traversal declares the governed movement before\nimplementation: source asset type; target asset type; edge traversal or\ngraph-function name; closure or evaluation obligation; lineage obligation;\nambiguity or gap obligation; allowed `F_D`, `F_P` and `F_H` bindings.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.2A%20Outcome-first%20realisation%20order",
          "start_line": 636
        }
      ],
      "key": "outcome_traversal",
      "label": "Outcome traversal"
    },
    {
      "conditions": [],
      "definition": "Machine-readable publication of retained functions, distinct from a callable surface existing only in prose or prompt memory.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 659,
          "quote": "The live line must publish a machine-readable function catalogue. At\nminimum each retained function should expose its name, inputs, outputs,\nintent, and public or helper role.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.3%20The%20function%20catalogue%20is%20published",
          "start_line": 656
        }
      ],
      "key": "function_catalogue",
      "label": "Function catalogue"
    },
    {
      "conditions": [],
      "definition": "Operative publication surface for public graph-function carriers, traversed graphs, typed nodes and vectors, and bound semantic jobs or equivalent outer callable contracts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 666,
          "quote": "The product must publish the public graph-function carriers, the graph or\ngraphs those carriers traverse, typed node and vector surfaces, and the\nsemantic jobs or equivalent outer callable contracts bound to the public\ncarrier.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.4%20The%20GTL%20module%20is%20the%20operative%20publication%20surface",
          "start_line": 663
        }
      ],
      "key": "gtl_module",
      "label": "GTL module"
    },
    {
      "conditions": [],
      "definition": "Review proving a unique execution authority for an affected traversal, including inspection of implementation surfaces rather than produced artifacts alone.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 711,
          "quote": "The audit must prove that exactly one execution authority exists for the\naffected traversal.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5B%20Execution%20authority%20audit",
          "start_line": 710
        }
      ],
      "key": "execution_authority_audit",
      "label": "Execution-authority audit"
    },
    {
      "conditions": ["ODD product over GTL/ABG"],
      "definition": "One constructive homeostasis loop from intent lineage and model synthesis through observation to lawful next action. Its four named functions are synthesize_model, eval_gap, evaluate_next and evaluate_action. It corrects toward required conditions without guaranteeing convergence or those conditions' adequacy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 796,
          "quote": "it corrects towards the required conditions as observations arrive,\nguarantees neither convergence nor the adequacy of those conditions, and\nits diagnoses distinguish the four causes named there (P2, P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 794
        }
      ],
      "key": "constructive_evaluation_loop",
      "label": "Constructive evaluation and yield loop"
    },
    {
      "conditions": [],
      "definition": "Selected Product outcome and any separately admitted bounded prerequisite or experiment basis; external authority constraining the loop, not authored, selected or enlarged by models, gaps, assurance, ledgers or projections.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 805,
          "quote": "Product models, gaps, assurance, ledgers and\nprojections may interpret that outcome but cannot author, select or\nenlarge it.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 800
        }
      ],
      "key": "selected_product_outcome",
      "label": "Selected Product outcome and bounded basis"
    },
    {
      "conditions": [],
      "definition": "Admitted source intent with lineage references from a human, imported source, prior product, intent engine or prior synthesized construction intent; ABG event-log truth that seeds the model without inventing graph actions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 840,
          "quote": "Admitted source intent and its lineage refs: human, imported source, prior product, intent engine, or prior synthesized construction intent.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 840
        }
      ],
      "key": "intent_lineage",
      "label": "IntentLineage"
    },
    {
      "conditions": [],
      "definition": "Desired and known typed asset model synthesized from intent lineage, prior model and admitted product truth; product-owned model truth published through admitted events and product projection references, without runtime-fact or action authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 841,
          "quote": "Desired and known typed asset model synthesized from intent lineage, prior model, and admitted product truth.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 841
        }
      ],
      "key": "product_asset_model",
      "label": "ProductAssetModel"
    },
    {
      "conditions": [],
      "definition": "Observable workspace, runtime archive, transform assets, product asset root, profile and file/process state. W is the mutable construction workspace; observation alone is not authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 842,
          "quote": "Current workspace, runtime archive, transform assets, product asset root, profile, and observed file or process state.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 842
        }
      ],
      "key": "worksite",
      "label": "Worksite"
    },
    {
      "conditions": [],
      "definition": "Append-only admitted runtime facts constituting ABG runtime truth; the immutable event/replay spine orders and anchors ledger entries using predecessor references.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 843,
          "quote": "| `RuntimeEventLog` | Append-only admitted runtime facts. | ABG runtime truth. |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 843
        }
      ],
      "key": "runtime_event_log",
      "label": "RuntimeEventLog"
    },
    {
      "conditions": [],
      "definition": "ABG projection truth: replay-derived current runtime state over event log and execution basis.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 844,
          "quote": "Replay-derived current runtime state over event log and execution basis.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 844
        }
      ],
      "key": "runtime_projection",
      "label": "RuntimeProjection"
    },
    {
      "conditions": [],
      "definition": "Read-only runtime truth plus construction-relevant worksite facts, carried by an ABG evaluator with product domain rows.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 845,
          "quote": "Read-only view of runtime truth plus worksite facts relevant to construction.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 845
        }
      ],
      "key": "observation_snapshot",
      "label": "ObservationSnapshot"
    },
    {
      "conditions": [],
      "definition": "Typed product-domain pressure over admitted observations of missing, partial, blocked, waiting or ambiguous assets and evidence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 846,
          "quote": "Typed pressure over missing, partial, blocked, waiting, or ambiguous assets and evidence.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 846
        }
      ],
      "key": "gap_pressure",
      "label": "GapPressureRow"
    },
    {
      "conditions": [],
      "definition": "Exact product-domain binding from gap pressure to selected Product outcome, any admitted prerequisite/experiment basis, target assets, required roles, evidence references and admissible graph outcomes, over GTL/ABG action authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 847,
          "quote": "Exact binding from gap pressure to the selected Product outcome, any admitted prerequisite or experiment basis, target assets, required roles, evidence refs, and admissible graph outcomes.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 847
        }
      ],
      "key": "target_obligation_binding",
      "label": "TargetObligationBinding"
    },
    {
      "conditions": [],
      "definition": "GTL/product publication consumed by ABG, naming lawful graph functions, vectors, targets, inputs and eligible outcomes.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 848,
          "quote": "Published lawful graph actions: graph functions, vectors, targets, inputs, and eligible outcomes.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 848
        }
      ],
      "key": "action_catalog",
      "label": "ActionCatalog"
    },
    {
      "conditions": [],
      "definition": "Dispatch sum type: initial_selection, post_yield_resume, post_close_graph_continuation, post_retry, post_repair, post_reenter, post_reprice or post_block. It is not another controller; post_reprice records a re-entry request without selection authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 849,
          "quote": "`initial_selection`, `post_yield_resume`, `post_close_graph_continuation`, `post_retry`, `post_repair`, `post_reenter`, `post_reprice`, or `post_block`.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 849
        }
      ],
      "key": "next_action_basis",
      "label": "NextActionBasis"
    },
    {
      "conditions": [],
      "definition": "Deterministic ranking of bound lawful actions under visible policy, using an ABG evaluator kernel and product policy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 850,
          "quote": "Deterministic ranking over bound lawful actions under visible policy.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 850
        }
      ],
      "key": "priority_projection",
      "label": "PriorityProjection"
    },
    {
      "conditions": [],
      "definition": "ABG-admitted selected action for one bounded graph invocation, preserving outcome/bounded-basis references through its target binding.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 851,
          "quote": "Admitted selected action for one bounded graph invocation, preserving the selected outcome or admitted bounded-basis refs carried by its target binding.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 851
        }
      ],
      "key": "construction_intent",
      "label": "ConstructionIntent"
    },
    {
      "conditions": [],
      "definition": "Worker, process, product, execution, materialization, liveness and postflight evidence admitted through ABG/product admission; worker self-closure is excluded.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 852,
          "quote": "Admitted worker, process, product, execution, materialization, liveness, and postflight evidence.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 852
        }
      ],
      "key": "admitted_evidence",
      "label": "AdmittedEvidence"
    },
    {
      "conditions": [],
      "definition": "Closure evidence and convergence for one edge attempt/version: counts, obligation rows, materialization, liveness and admission references, and edge_converged. It does not select actions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 853,
          "quote": "Evidence and convergence carrier for one edge attempt or version.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 853
        }
      ],
      "key": "edge_fulfillment_ledger",
      "label": "EdgeFulfillmentLedger"
    },
    {
      "conditions": [],
      "definition": "Closed seven-decision vocabulary over the ledger: close, yield, retry, repair, re-enter, reprice, block. Cause refinements add no decisions. Each decision is replay-visible with reproducible basis and reason references.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 854,
          "quote": "Sum type over the ledger: close, yield, retry, repair, re-enter, reprice, block.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 854
        }
      ],
      "key": "edge_closure_decision",
      "label": "EdgeClosureDecision"
    },
    {
      "conditions": [],
      "definition": "ABG next-action evaluation read model with product policy, observing NextActionBasis and current truth to select a graph action only when lawful.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 855,
          "quote": "Read model that observes `NextActionBasis` plus current truth and selects a next graph action only when lawful.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 855
        }
      ],
      "key": "next_action_projection",
      "label": "NextActionProjection"
    },
    {
      "conditions": [],
      "definition": "Model synthesis from event-log-backed IntentLineage, prior ProductAssetModel and admitted product truth, producing ProductAssetModel.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 863,
          "quote": "`IntentLineage + prior ProductAssetModel + admitted product truth`",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 863
        }
      ],
      "key": "synthesize_model",
      "label": "synthesize_model"
    },
    {
      "conditions": [],
      "definition": "Read-only comparison of ProductAssetModel with RuntimeEventLog, RuntimeProjection and Worksite, producing ObservationSnapshot and GapPressureRow.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 864,
          "quote": "`ProductAssetModel + RuntimeEventLog + RuntimeProjection + Worksite`",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 864
        }
      ],
      "key": "eval_gap",
      "label": "eval_gap"
    },
    {
      "conditions": [],
      "definition": "Total next-action selection from NextActionBasis, fresh eval_gap, TargetObligationBinding, ActionCatalog and Policy; produces PriorityProjection, NextActionProjection and selected_action, or a typed no-action with its own core result.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 865,
          "quote": "`NextActionBasis + fresh eval_gap + TargetObligationBinding + ActionCatalog + Policy`",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 865
        }
      ],
      "key": "evaluate_next",
      "label": "evaluate_next"
    },
    {
      "conditions": [],
      "definition": "Evaluation of the action just taken from ConstructionIntent, AdmittedEvidence, TargetObligationBinding and Policy, producing EdgeFulfillmentLedger and EdgeClosureDecision.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 866,
          "quote": "`ConstructionIntent + AdmittedEvidence + TargetObligationBinding + Policy`",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 866
        }
      ],
      "key": "evaluate_action",
      "label": "evaluate_action"
    },
